def synthetic_venue_status_config(case_id: str = "MV05") -> ConfigSpec:
    """Detached config for a synthetic multi-venue status case (contract fixture id).

    Entity SYN/X/S; session [0, 100) so every certificate covers it; evaluation time 100.
    Reconstruction cases carry the label "synthetic replay". Built with the public
    make_multivenue_status_config; no expected value or reduction is involved.
    """
    cutoff, knowledge, mode, selection, _slots = _synthetic_case(case_id)
    population_id, revision, epoch, max_age_ns, dimensions, precedence = selection
    availability = AvailabilitySpec(cutoff, knowledge, 100, mode,
                                    "synthetic replay" if mode == "reconstruction" else None)
    return make_multivenue_status_config(
        population_id=population_id, population_revision=revision, epoch=epoch,  # type: ignore[arg-type]
        precedence=precedence, clock_dimensions=dimensions,  # type: ignore[arg-type]
        max_age_ns=max_age_ns,  # type: ignore[arg-type]
        session=SessionSpec(_NAMESPACE, _SESSION, 0, 100, "UTC"),
        window=WindowSpec(1, _SESSION, (_SESSION,), "completed_eod"), availability=availability)


def synthetic_venue_status_fixture(case_id: str = "MV05") -> VenueStatusInputs:
    """Original synthetic facts for a contract result fixture; no expected values.

    Population and fact rows are exactly the fixture's, including a missing (None)
    slot, covered-empty slots and the declared coverage (e.g. incomplete MV24/MV25).
    It never derives a count, aggregate, precedence or clock, and supplies no
    observed-source capability or rights evidence.
    """
    batches: list[CanonicalBatch | None] = []
    for slot in _synthetic_case(case_id)[4]:
        if slot is None:
            batches.append(None)
            continue
        input_id, source_id, snapshot_id, expected, observed, complete, rows = slot
        metadata = BatchMetadata(_NAMESPACE, SourceBinding(source_id, snapshot_id, MAPPING_VERSION, input_id),  # type: ignore[arg-type]
                                 Coverage(expected, observed, complete), None)  # type: ignore[arg-type]
        batches.append(make_venue_batch(rows, metadata=metadata,  # type: ignore[arg-type]
                                        instrument_id=_INSTRUMENT, session_id=_SESSION))
    population, seed, states, prefix, validity = batches
    return VenueStatusInputs(population, seed, states, prefix, validity,
                             provenance=tuple("unavailable" if b is None else "synthetic" for b in batches))


__all__ += ["SYNTHETIC_VENUE_STATUS_CASES", "synthetic_venue_status_config", "synthetic_venue_status_fixture"]
